-- EXPLAIN of an UPDATE or DELETE of a partitioned table lists each
-- partition it reaches as a result relation of the write (`Update on pt1
-- pt_1`) and scans them under an Append, or one partition alone; a write
-- no partition survives reads a Result with a false One-Time Filter.
-- VERBOSE scans return each row's tableoid with its ctid; EXPLAIN ANALYZE
-- counts each partition's scan, and executes only the partitions pruning
-- keeps.
CREATE TABLE pt601 (id int, v int) PARTITION BY RANGE (id);
CREATE TABLE pt601_1 PARTITION OF pt601 FOR VALUES FROM (1) TO (10);
CREATE TABLE pt601_2 PARTITION OF pt601 FOR VALUES FROM (10) TO (20);
CREATE TABLE pt601_3 PARTITION OF pt601 FOR VALUES FROM (20) TO (30);
EXPLAIN (COSTS OFF) UPDATE pt601 SET v = 0 WHERE id = 3;
EXPLAIN (COSTS OFF) DELETE FROM pt601;
EXPLAIN (COSTS OFF) DELETE FROM pt601 WHERE id < 13;
EXPLAIN (COSTS OFF) UPDATE pt601 SET v = 1 WHERE id > 1000 AND id < 0;
EXPLAIN (COSTS OFF) DELETE FROM pt601 WHERE id = 500;
EXPLAIN (COSTS OFF) DELETE FROM ONLY pt601;
EXPLAIN (COSTS OFF) UPDATE pt601 x SET v = 2 WHERE x.id >= 20;
EXPLAIN (VERBOSE, COSTS OFF) UPDATE pt601 SET v = 0 WHERE id < 13;
EXPLAIN (VERBOSE, COSTS OFF) UPDATE pt601 SET v = v + 1 WHERE id = 25;
EXPLAIN (VERBOSE, COSTS OFF) DELETE FROM pt601 WHERE id < 13;
EXPLAIN (FORMAT JSON, COSTS OFF) UPDATE pt601 SET v = 1 WHERE id < 15;
EXPLAIN (FORMAT YAML, COSTS OFF) DELETE FROM pt601 WHERE id = 3;
INSERT INTO pt601 SELECT g, g FROM generate_series(1, 29) g;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) UPDATE pt601 SET v = 0 WHERE id < 13;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) DELETE FROM pt601 WHERE id = 25;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) DELETE FROM pt601 WHERE v = 0;
SELECT * FROM pt601 ORDER BY id;
CREATE TABLE lt601 (k text, v int) PARTITION BY LIST (k);
CREATE TABLE lt601_a PARTITION OF lt601 FOR VALUES IN ('a');
CREATE TABLE lt601_d PARTITION OF lt601 DEFAULT;
EXPLAIN (COSTS OFF) UPDATE lt601 SET v = 1 WHERE k = 'q';
EXPLAIN (COSTS OFF) DELETE FROM lt601 WHERE k IS NULL OR k = 'a';
